const payload = $json.body ?? $json;
const headers = $json.headers ?? {};

const title = payload.issue?.title ?? '';
const body = payload.issue?.body ?? '';
const text = `${title} ${body}`.toLowerCase();

let classification = 'other';
if (/security|seguran|vulnerab|cve|xss|sql injection/.test(text)) classification = 'security';
else if (/bug|erro|error|falha|500|quebra|crash|defeito/.test(text)) classification = 'bug';
else if (/feature|melhoria|adicionar|novo recurso|enhancement/.test(text)) classification = 'feature';
else if (/doc|documenta|readme|manual/.test(text)) classification = 'documentation';

let priority = 'normal';
if (/security|seguran|vulnerab|cve|produção|production|crítico|critical|urgente/.test(text)) priority = 'high';

return [{
  json: {
    deliveryId: headers['x-github-delivery'] ?? null,
    eventType: headers['x-github-event'] ?? 'issues',
    action: payload.action ?? null,
    repository: payload.repository?.full_name ?? null,
    sender: payload.sender?.login ?? null,
    issue: {
      number: payload.issue?.number ?? null,
      title,
      url: payload.issue?.html_url ?? null
    },
    classification,
    priority,
    payload
  }
}];
